// === Tab: mySketch.js ===
/*  Created for #WCCChallenge "Phenomena"

This sketch creates an abstract hurricane effect. I am using the spiralSDF
function from Lygia to generate the spirals. There is also a moving circle to simulate
the idea of a moving center to the storm. I am using the syntax from the flip
turn sketch to add multiple movers.

Notes: 
Spiral Boundaries: lower number gives spirals more freedom to move
detaTurns: determines thickness of spirals

AI Disclosure: I got help from chatGPT figuring out how to rotate the spirals in local 
space (rotateAroundCenter() function in the frag file).

References:
https://github.com/patriciogonzalezvivo/lygia/tree/main
*/

let myShader, canvas;
const MAX_MOVERS = 14;

let movers = [];

let params = {
	edge: 0.3,
   rotationSpeed: 0.25,
	spiralTurns: 0.3,
	deltaTurns: 0.1,
	num_movers: 6,
	Screenshot: saver
}

async function setup() {
	let canvasSize = max(windowWidth, windowHeight);
   createCanvas(windowWidth, windowWidth*0.75, WEBGL);
	//canvas.position(windowWidth / 2, windowWidth*0.75 / 2);

	pixelDensity(1);
	noStroke();

	const guiContainer = createDiv();
	guiContainer.id("gui");
	guiContainer.parent(document.body);

	gui = new lil.GUI({
		container: document.getElementById("gui"),
	});
	gui.add(params, "edge", 0.10, 0.4, 0.01).name("Spiral Boundaries")
	gui.add(params, "rotationSpeed", 0.0, 3.0, 0.05).name("Rotation Speed")
	//gui.add(params, "spiralTurns", 0.3, 1.0, 0.01).name("Spiral Turns")
	gui.add(params, "deltaTurns", 0.01, 0.2, 0.01).name("Spiral Thickness")
	gui.add(params, "num_movers", 1, MAX_MOVERS, 1).name("Number of Spirals")
	gui.add(params, 'Screenshot'); 

	myShader = await createShader(resolveLygia(vert), resolveLygia(frag));

	// create movers
	for (let i = 0; i < MAX_MOVERS; i++) {
		let scale = 0.8 + i * 0.05;
		movers.push(new Mover(params.edge, scale));
	}

	pixelDensity(2)
}

function draw() {
	shader(myShader);
	myShader.setUniform("u_resolution", [width, height]);
	myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	myShader.setUniform("u_time", millis() / 1000.0);
	myShader.setUniform("rotationSpeed", params.rotationSpeed);
	myShader.setUniform("uCount", params.num_movers);
	myShader.setUniform("deltaTurns", params.deltaTurns);
	myShader.setUniform("spiralTurns", params.spiralTurns);


	// pack arrays
	let pos = [];
	var scale = [];
	let n = params.num_movers

	for (let i = 0; i < n; i++) {
		let mover = movers[i];
		// Pass position and scale to shader
		pos.push(mover.x, mover.y);
      scale.push(mover.scale);
		// Update each movers position
		mover.update();
	}

	myShader.setUniform("uPos", pos);
	myShader.setUniform("uScale", scale);

	rect(0, 0, width, height);
}

function saver(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// function findAveragePosition() {
// 	let sumX = 0;
