// }

const vert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }`;

const frag = `#version 300 es
precision highp float;
out vec4 O;

#define MAX_MOVERS 10

uniform vec2  u_resolution; 
uniform float u_time;
uniform vec2  u_mouse;
uniform int   uCount;
uniform float rotationSpeed;
uniform float deltaTurns;
uniform float spiralTurns;
uniform vec2  uPos[MAX_MOVERS];
uniform float uScale[MAX_MOVERS];

#include "lygia/math/const.glsl"
#include "lygia/math/rotate2d.glsl"
#include "lygia/space/aspect.glsl"
#include "lygia/sdf/circleSDF.glsl"
#include "lygia/sdf/spiralSDF.glsl"
#include "lygia/generative/random.glsl"
#include "lygia/space/center.glsl"

vec3 palette0(float t) {
vec3 a = vec3(0.97, 0.0, 0.556);
 vec3 b = vec3(0.929, 0.991, 0.012);
 vec3 c = vec3(1.0, 1.0, 3.0);
 vec3 d = vec3(0.5, 0.5, 0.362);
 return a + b * cos( TAU*(c * t + d) );

}

// raspberry/turquoise
vec3 palette1( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5); // Baseline brightness for the colors
    vec3 b = vec3(0.5, 0.5, 0.5); // Contrast/Intensity of the color waves
    vec3 c = vec3(2.0, 1.0, 0.0); //
	 vec3 d = vec3(0.5, 0.2, 0.25);

    return a + b * tan( TAU*(c * t + d) );
}

// gold/teal
vec3 palette2( float t ) {
    vec3 a = vec3(0.9, 0.5, 0.8); // Baseline brightness for the colors
    vec3 b = vec3(0.5, 0.5, 0.5); // Contrast/Intensity of the color waves
    vec3 c = vec3(1.0, 1.0, 0.5); //
    vec3 d = vec3(0.8, 0.9, 0.3);

    return a + b * tan( TAU*(c * t + d) );
}

//teal/red
vec3 palette3( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5); // Baseline brightness for the colors
    vec3 b = vec3(0.5, 0.9, 0.5); // Contrast/Intensity of the color waves
    vec3 c = vec3(1.0, 1.0, 1.0); //
    vec3 d = vec3(0.3, 0.2, 0.2);

    return a + b * cos( TAU*(c * t + d) );
}

// blues
//https://editor.p5js.org/jcponce/sketches/G_83s9d0k
vec3 palette4( float t ) {
    vec3 a = vec3(0.198, 0.438, 0.698);
    vec3 b = vec3(-0.262, 0.208, 0.238);
    vec3 c = vec3(2.238, 2.168, 1.000);
    vec3 d = vec3(-0.052, 0.333, 0.667);

    return a + b * tan( TAU*(c * t + d) );
}

// yellow/blue
vec3 palette5( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.78, 0.666, 0.497);

    return a + b * tan( TAU*(c * t + d) );
}

// purple gold
vec3 palette6( float t ) {
   vec3 a = vec3(0.5, 0.5, 0.5); // Baseline brightness for the colors
    vec3 b = vec3(0.5, 0.5, 0.5); // Contrast/Intensity of the color waves
    vec3 c = vec3(1.0, 0.7, 0.4); //
    vec3 d = vec3(0.0, 0.15, 0.2);

    return a + b * sin( TAU*(c * t + d) );
}

// gold/blue
vec3 palette7( float t ) {
   vec3 a = vec3(0.5, 0.5, 0.5); // Baseline brightness for the colors
    vec3 b = vec3(0.5, 0.5, 0.5); // Contrast/Intensity of the color waves
    vec3 c = vec3(1.0, 1.0, 1.0); //
    vec3 d = vec3(0.0, 0.1, 0.2);

    return a + b * cos( TAU*(c * t + d) );
}

vec3 palette8( float t ) {
   vec3 a = vec3(0.15, 0.5, 0.45); // Baseline brightness for the colors
    vec3 b = vec3(0.2, 0.5, 0.15); // Contrast/Intensity of the color waves
    vec3 c = vec3(2.4, 0.45, 0.55); //
    vec3 d = vec3(0.0, 0.5, 0.55);

    return a + b * cos( TAU*(c * t + d) );
}

// From chatGPt
vec2 rotateAroundCenter(vec2 p, float a) {
    p -= 0.5;
    p = rotate2d(a) * p;
    return p + 0.5;
}

float drawMovers(vec2 uv, int i) {
  float a = u_time * rotationSpeed;
  vec2 moverPos = rotateAroundCenter(uPos[i], a);
  vec2 p = uv - moverPos;
  float scale = uScale[i];   
  p /= scale;             

  float d1 = spiralSDF(p, spiralTurns);
  float d2 = spiralSDF(p, spiralTurns-deltaTurns);

  float d =  smoothstep(0.1, 0.01, d1-d2); 
  return d * 0.5 + 0.5;
  // return (d1 - d2)*0.5 + 0.5;
}

void main(void) {
    vec4 color = vec4(vec3(0.0), 1.0);
    vec2 pixel = 0.5/u_resolution.xy;
    vec2 st = gl_FragCoord.xy * pixel;

    float d;
    for (int i = 0; i < MAX_MOVERS; i++) {
    if (i >= uCount) break;
	 d += drawMovers(st+0.75, i); // I have moved st to offset for moving pos
  }

   d += circleSDF(st+0.5-uPos[0]); // I have moved st to offset for moving pos
   color.rgb = palette7(d);

   O = color;
}`;

// === Tab: mover.js ===
class Mover {
	constructor(edge, scale = 1) {
		this.edge = edge;
		this.scale = max(scale, 1.5);
		this.x = random(edge, 1-edge);
		this.y = random(edge, 1-edge);
		this.speed = 0.0015;
		this.vx = random(-this.speed, this.speed);
		this.vy = random(-this.speed, this.speed);

	}

	update() {
		this.x += this.vx;
		this.y += this.vy;
		if (this.x <= this.edge || this.x >= 1-this.edge) this.vx *= -1;
		if (this.y <= this.edge || this.y >= 1-this.edge) this.vy *= -1;
	}
}

